nltl:QuantityValueShape
    a sh:NodeShape ;
    sh:class qudt:QuantityValue ;
    sh:property [
        sh:path qudt:value ;
        sh:minCount 1 ;
        sh:maxCount 1 ;
        sh:datatype xsd:decimal ;
        sh:message "The displacement quantity value must be represented by exactly one xsd:decimal value."
    ] ;
    sh:property [
        sh:path qudt:unit ;
        sh:minCount 1 ;
        sh:maxCount 1 ;
        sh:hasValue unit:KiloTON_Metric ;
        sh:message "The displacement quantity must use http://qudt.org/vocab/unit/KiloTON_Metric (kt)."
    ] .

sh:sparql [
        a sh:SPARQLConstraint ;
        sh:message "The ship displacement must be the displacement of a linked upper ice waterline case having the greatest displacement." ;
        sh:select """
            PREFIX nltl: <https://w3id.org/nltl/vocab#>
            PREFIX qudt: <http://qudt.org/schema/qudt/>
            PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

            SELECT $this
            WHERE {
                $this nltl:upperIceWaterlineDisplacement ?shipQuantity .
                ?shipQuantity qudt:value ?shipDisplacement .

                FILTER (
                    NOT EXISTS {
                        $this nltl:hasUpperIceWaterlineCase ?equalCase .
                        ?equalCase nltl:waterlineCaseDisplacement ?equalQuantity .
                        ?equalQuantity qudt:value ?equalDisplacement .
                        FILTER (
                            xsd:decimal(str(?equalDisplacement)) =
                            xsd:decimal(str(?shipDisplacement))
                        )
                    }
                    ||
                    EXISTS {
                        $this nltl:hasUpperIceWaterlineCase ?greaterCase .
                        ?greaterCase nltl:waterlineCaseDisplacement ?greaterQuantity .
                        ?greaterQuantity qudt:value ?greaterDisplacement .
                        FILTER (
                            xsd:decimal(str(?greaterDisplacement)) >
                            xsd:decimal(str(?shipDisplacement))
                        )
                    }
                )
            }
        """
    ]

sh:path qudt:value ;
        sh:minCount 1 ;
        sh:maxCount 1 ;
        sh:datatype xsd:decimal ;

sh:path qudt:unit ;
        sh:minCount 1 ;
        sh:maxCount 1 ;
        sh:hasValue unit:KiloTON_Metric ;
